-- Dansk portion 4 del 3/3: 166 MC-spørgsmål på sværhedsskalaen 1-10.000, niveau 6587-9982.
-- Del af de 5.000 nye danskopgaver. Skrevet fra bunden til dansk folkeskole, 3.-9. klasse.
-- Genereret af tools/questions/build-danish-5000.mjs; ret i tools/questions/fixtures/danish-5000/, ikke her.
-- Kræver migration A (20261020120000_difficulty_scale_a): kolonnen questions.difficulty_level.
--
-- Niveau: hver opgave har et eksplicit difficulty_level (forfatterens skøn, ikke en måling).
-- target_grade/difficulty_band er afledt baglæns af niveauet (cellen i §4.1).
--
-- INAKTIV VED INDSÆTTELSEN: alle rækker får is_active=false og metadata.level_batch='danish4'.
-- Aktivering er en SEPARAT migration efter dokumenteret stikprøvekontrol og særskilt ejergodkendelse.
-- Må KUN anvendes via apply_migration med særskilt ejer-autorisation (D-110).

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band, difficulty_level)
SELECT
  jsonb_build_object('question', e->>'q', 'options', e->'o', 'correct', e->>'a',
                     'accepted_answers', jsonb_build_array(e->>'a'), 'review_text', e->>'r'),
  'mc', 'short',
  jsonb_build_object('concepts', jsonb_build_array(m.concept), 'cognitive_skill', m.skill,
                     'difficulty_type', m.dtype, 'misconception_type', m.mis,
                     'challenge_role', e->>'role', 'insight_type', e->>'insight',
                     'practice_variant', e->>'variant',
                     'level_batch', 'danish4', 'domain', 'danish'),
  'mc_single', (e->>'b')::int, 'auto', false, 'danish', (e->>'g')::int,
  (e->>'b')::int, (e->>'l')::int
FROM jsonb_array_elements($$[
{"l":6587,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvad er det direkte objekt i: 'Bedstefar fortalte os en sjov historie.'?","o":["os","Bedstefar","en sjov historie","fortalte"],"a":"en sjov historie","r":"Spørg: Hvad fortalte bedstefar? 'Os' er indirekte objekt, fordi det siger, hvem historien blev fortalt til."},
{"l":6609,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"I hvilken sætning kan 'som' ikke erstattes af 'der'?","o":["Manden, som bor her, er venlig.","Hunden, som gøede, var sort.","Bussen, som kom sent, var fuld.","Filmen, som vi så, var lang."],"a":"Filmen, som vi så, var lang.","r":"'Der' kan kun stå som grundled i relativsætningen. I 'som vi så' er 'vi' grundled, så 'der' kan ikke bruges."},
{"l":6630,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvilket ord mangler? 'Om aftenen tager jeg min ___ på og går i seng.'","o":["pyjamas","pyjammas","pyjamaz","pygamas"],"a":"pyjamas","r":"Ordet skrives med y, j og ét m, og det ender på s."},
{"l":6651,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Læs: 'Du vågner ved, at telefonen ringer. Du ved allerede, hvem det er, og du lader den ringe.' Hvilken fortællerform er det?","o":["jeg-fortæller","du-fortæller","vi-fortæller","alvidende fortæller"],"a":"du-fortæller","r":"Teksten er fortalt i 'du'-form, så læseren næsten selv bliver hovedpersonen. Det er en sjælden, men virkningsfuld form."},
{"l":6671,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Klubben stiller spilleren et 'ultimatum'. Hvad er det?","o":["et tilbud om en ny og bedre kontrakt","en tak for mange års god indsats","et sidste krav, ellers får det følger","en plan for næste sæsons træning"],"a":"et sidste krav, ellers får det følger","r":"Et ultimatum er det sidste ord i en sag. Hvis kravet ikke bliver opfyldt inden fristen, sker der noget bestemt."},
{"l":6693,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Insulin er et 'hormon'. Hvad er et hormon?","o":["en bakterie, der hjælper med fordøjelsen af mad","en celle, der bekæmper infektioner","en muskel, der pumper blodet rundt","et stof, der sender besked rundt i kroppen"],"a":"et stof, der sender besked rundt i kroppen","r":"Hormoner dannes i kirtler og føres rundt med blodet. Insulin styrer for eksempel blodets indhold af sukker."},
{"l":6708,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad kaldes det, når en smitsom sygdom spreder sig over store dele af verden?","o":["en pandemi","en vaccine","en diagnose","en karantæne"],"a":"en pandemi","r":"'Pan' betyder alt eller alle. Forstavelsen fortæller, at sygdommen ikke holder sig til ét land eller område."},
{"l":6730,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvad betyder s-formen i: 'Vi ses i morgen'?","o":["at nogen ser os","at vi ser hinanden","at vi ser os selv","at vi ser noget"],"a":"at vi ser hinanden","r":"Her er s-formen gensidig: Handlingen går begge veje. Det samme gælder for 'mødes' og 'skændes'."},
{"l":6752,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Haven hører til huset. Hvilket stedord skal stå: 'Huset og ___ have ligger ved åen.'?","o":["dens","sin","dets","hans"],"a":"dets","r":"'Huset' er intetkøn, så ejestedordet hedder 'dets'. 'Sin' kan ikke stå inde i grundleddet."},
{"l":6772,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Lygterne tændte én for én langs kajen, mens færgen lagde fra. Hun stod ved rælingen, til byen kun var en prik. Så tog hun billedet op af lommen og lod det glide ned i vandet.' Hvad betyder hendes handling sandsynligvis?","o":["At hun ved et uheld taber billedet","At hun vil vise byen til en anden","At hun vil hjem igen med det samme","At hun vil lægge noget bag sig"],"a":"At hun vil lægge noget bag sig","r":"Hun venter, til byen næsten er væk, og slipper så billedet med vilje. Det ligner et farvel til noget, hun vil være færdig med."},
{"l":6791,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad er en 'klumme' i en avis?","o":["en kort, personlig tekst med et synspunkt","en oversigt over børskurser og valuta","en kort notits om et trafikuheld","en lang artikel med mange kilder"],"a":"en kort, personlig tekst med et synspunkt","r":"En klumme står ofte fast samme sted i avisen. Skribenten må gerne være personlig og sjov, når en sag bliver kommenteret."},
{"l":6800,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Spørgeskema til eleverne, spørgsmål 3: Er du ikke også enig i, at de alt for korte frikvarterer burde forlænges?' Hvad er problemet med spørgsmålet?","o":["Det er for svært at forstå for en elev","Det skubber svareren i en bestemt retning","Det handler slet ikke om frikvarterer","Det giver svareren alt for mange valg"],"a":"Det skubber svareren i en bestemt retning","r":"'Ikke også' og 'alt for korte' lægger svaret i munden på eleven. Det kaldes et ledende spørgsmål."},
{"l":6821,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvilken sætning indeholder en personifikation?","o":["Solen var en gul appelsin.","Solen skinnede hele dagen.","Solen smilede til vandrerne.","Solen var varm som en ovn."],"a":"Solen smilede til vandrerne.","r":"At smile er noget, mennesker gør. Solen får altså en menneskelig handling, og det er personifikation."},
{"l":6843,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"I en ny lov står der: 'Ikrafttræden: 1. januar.' Hvad sker der den dag?","o":["loven bliver foreslået","loven bliver ophævet","loven bliver diskuteret","loven begynder at gælde"],"a":"loven begynder at gælde","r":"En lov kan være vedtaget, længe før den virker. Først ved ikrafttræden skal den følges."},
{"l":6864,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvad kaldes personer, der kun spiller en mindre rolle i en fortælling?","o":["bipersoner","hovedpersoner","modtagere","afsendere"],"a":"bipersoner","r":"Bipersoner støtter handlingen, men historien handler ikke først og fremmest om dem."},
{"l":6883,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Udsagnsordet 'modernisere' er dannet af tillægsordet 'moderne'. Hvad betyder det?","o":["at bevare noget præcis, som det er","at forny noget, så det passer til i dag","at kritisere alt det, der er nyt","at flytte noget til et nyt sted"],"a":"at forny noget, så det passer til i dag","r":"Endelsen -isere betyder ofte 'at gøre noget til'. På samme måde er 'at effektivisere' at gøre noget mere effektivt."},
{"l":6903,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad står der rigtigt? 'Min ___ for rummet startede, da jeg var seks år.'","o":["intresse","interese","interesse","interrese"],"a":"interesse","r":"Ordet har ét r og dobbelt-s. Husk e'et mellem t og r, selvom det sluges i talen."},
{"l":6926,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvad kaldes 'spist' i 'Vi har spist' på latin?","o":["præsens participium","imperativ","infinitiv","perfektum participium"],"a":"perfektum participium","r":"Kort tillægsform hedder perfektum participium, og den står sammen med 'har' eller 'er' i førnutid."},
{"l":6944,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Læs: 'På den ene side af søen larmede tivoliet med lys og musik. På den anden side stod skoven mørk og stille.' Hvilket virkemiddel fremhæver forskellen?","o":["kontrast","allitteration","foregribelse","rim"],"a":"kontrast","r":"De to sider af søen sættes op mod hinanden: lys og larm på den ene, mørke og stilhed på den anden. Det kaldes kontrast."},
{"l":6966,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"'Det er en plausibel forklaring.' Hvad betyder 'plausibel' her?","o":["overflødig","sandsynlig","fornærmende","hemmelig"],"a":"sandsynlig","r":"En plausibel forklaring lyder rimelig og troværdig, selv om den ikke er bevist."},
{"l":6988,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Emil er 'indifferent' over for at flytte. Hvordan har han det?","o":["han er helt sikker på, at han vil flytte","han er stærkt imod at flytte","han er ligeglad med, om han flytter","han glæder sig meget til at flytte"],"a":"han er ligeglad med, om han flytter","r":"Indifferent betyder uden interesse for sagen. Ordet er dannet af 'in-', som betyder ikke, og 'different', som betyder forskellig: det gør ingen forskel for ham."},
{"l":7003,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Jeg er træt af at høre, at min generation er doven. Den siges også at være stresset af for meget arbejde. Begge dele på én gang kræver i hvert fald, at man har travlt.' Hvad vil skribenten vise?","o":["At unge i virkeligheden er både dovne og stressede","At de voksne arbejder mere end de unge gør","At stress er værre end dovenskab for de unge","At påstandene om de unge modsiger hinanden"],"a":"At påstandene om de unge modsiger hinanden","r":"Skribenten stiller doven og stresset op som to ting, der ikke passer sammen. Den sidste sætning gør grin med modsigelsen."},
{"l":7024,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvilken genre er en længere, holdningspræget artikel i en avis, ofte skrevet af en ekspert uden for redaktionen?","o":["kronik","leder","notits","reportage"],"a":"kronik","r":"En kronik er skrevet af en gæsteskribent og behandler et emne grundigt. En leder er avisens egen holdning."},
{"l":7046,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvilket sammensat ord er stavet rigtigt? 'Den 31. december er det ___.'","o":["nytårs aften","nytårsaften","nytåraften","nytårsaffen"],"a":"nytårsaften","r":"Ordet samles med et fuge-s efter 'nytår' og skrives i ét ord."},
{"l":7069,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvorfor giver passiv god mening i: 'Cyklen blev stjålet i nat.'?","o":["Cyklen er den, der gør noget her.","Det viser tydeligt, hvem tyven er.","Man ved ikke, hvem der gjorde det.","Passiv viser, at det sker lige nu."],"a":"Man ved ikke, hvem der gjorde det.","r":"Med passiv behøver man ikke nævne den, der handler. Det er nyttigt, når personen er ukendt eller uvigtig."},
{"l":7086,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Der lød 'homerisk latter' fra salen. Hvad betyder det?","o":["en stille og høflig latter","en ond latter, der skal såre andre","en falsk latter, der ikke er ægte","en voldsom latter, der ikke vil stoppe"],"a":"en voldsom latter, der ikke vil stoppe","r":"Udtrykket kommer af Homers digte, hvor guderne bryder ud i en latter, der ikke vil stilne af."},
{"l":7108,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Forslaget kan 'åbne Pandoras æske'. Hvad frygter man?","o":["at der slippes problemer løs, som ikke kan standses","at der afsløres en hemmelig gave til nogen","at der opdages en skat, som skal deles mellem alle","at der forsvinder et vigtigt dokument for altid"],"a":"at der slippes problemer løs, som ikke kan standses","r":"I den græske myte åbner Pandora en krukke eller æske, og alle verdens plager slipper ud."},
{"l":7135,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvordan ville man skrive 'Det var en dårlig idé' i en formel rapport?","o":["Ideen var virkelig dårlig, synes jeg.","Forslaget var uhensigtsmæssigt.","Forslaget var helt håbløst.","Det var en rigtig ringe plan."],"a":"Forslaget var uhensigtsmæssigt.","r":"En rapport skal være saglig og uden store følelser. 'Uhensigtsmæssigt' siger, at forslaget ikke var godt, mens 'håbløst', 'rigtig ringe' og 'synes jeg' lyder som en samtale."},
{"l":7155,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad skal der stå? 'I et ___ har alle brug for hinanden, også selvom de ikke kender hinanden.'","o":["samfun","sammfund","samfund","samfundt"],"a":"samfund","r":"Ordet består af 'sam' og 'fund'. Det stumme d skal med, og der er kun ét m."},
{"l":7174,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvilket digt regnes for startskuddet til romantikken i Danmark?","o":["Jens Vejmand","Barndommens gade","I Danmark er jeg født","Guldhornene"],"a":"Guldhornene","r":"'Guldhornene' blev skrevet i 1802 og blev et symbol på den nye romantiske digtning."},
{"l":7197,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Find det rigtige ord: 'På ferien i Spanien mødte Jonas en ___, der også kom fra Danmark.'","o":["landsmand","landmand","lansmand","lanmand"],"a":"landsmand","r":"En landsmand er en fra samme land som en selv. Fuge-s'et skiller ordet fra 'landmand', der er en bonde."},
{"l":7214,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'På pakken står der: 9 ud af 10 hundeejere vil anbefale Gnavefryd-tyggeben. Med småt står der, at man spurgte 10 hundeejere. De havde alle fået et års forbrug gratis af firmaet.' Hvorfor er påstanden på pakken svag som bevis?","o":["Tallet 9 ud af 10 er for højt til at kunne være sandt","Der blev kun spurgt ti, og de fik gratis tyggeben","Hundeejerne har kun prøvet tyggebenene i ganske kort tid","Den tiende hundeejer er slet ikke med i undersøgelsen"],"a":"Der blev kun spurgt ti, og de fik gratis tyggeben","r":"Ti personer er for få, og den, der får noget gratis, er ikke den bedste at spørge. Et højt tal kan virke mistænkeligt, men svagheden ligger i, hvem der blev spurgt."},
{"l":7235,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad gør et rejseselskab, der 'kompenserer' passagererne efter en aflyst tur?","o":["beder dem betale et ekstra gebyr","beder dem vente til næste år","giver dem erstatning for tabet","sender dem en beskrivelse af turen"],"a":"giver dem erstatning for tabet","r":"At kompensere er at opveje noget, der er gået tabt. Man kan også kompensere for en svaghed ved at være god til noget andet."},
{"l":7256,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket sætningsled er ledsætningen i: 'Jeg ved ikke, hvor Sara bor.'?","o":["grundled","hensynsled","omsagnsled","genstandsled"],"a":"genstandsled","r":"Spørg: Hvad ved jeg ikke? Svaret er hele ledsætningen, så den fungerer som genstandsled."},
{"l":7278,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken ordklasse siger relativsætningen noget nærmere om i: 'Den bil, som står der, er min.'?","o":["navneord","udsagnsord","bindeord","forholdsord"],"a":"navneord","r":"Relativsætningen 'som står der' beskriver navneordet 'bil'. Den fortæller, hvilken bil der er tale om."},
{"l":7300,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Læs: 'Da jeg var barn, troede jeg, at min far kunne alt. Nu, tredive år senere, ser jeg, hvor nervøs han var, da han lærte mig at svømme.' Hvordan er fortællersituationen?","o":["Et barn fortæller om det, der sker lige nu","En voksen jeg-fortæller ser tilbage på barndommen","En alvidende fortæller kender alles inderste tanker","En ydre fortæller beskriver kun, hvad folk gør"],"a":"En voksen jeg-fortæller ser tilbage på barndommen","r":"Fortælleren siger 'jeg' og ser barndommen med voksne øjne. Afstanden gør, at han nu forstår mere end dengang."},
{"l":7317,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"I gamle romaner hører man om 'tyendet' på gården. Hvem er det?","o":["gårdens børn","gårdens gæster","gårdens tjenestefolk","gårdens husdyr"],"a":"gårdens tjenestefolk","r":"Tyende er et gammelt ord for tjenestefolk: karle, piger og andre, der arbejdede for kost og løn på en gård."},
{"l":7337,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Find ordet: 'Den nye regel havde en god ___ på støjen i klassen.'","o":["efekt","effeckt","effægt","effekt"],"a":"effekt","r":"Ordet har dobbelt-f og ender på -kt uden c."},
{"l":7355,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken ledsætning har rigtig ordstilling: 'Hun blev glad, …'?","o":["da hun endelig havde fundet nøglerne","da hun havde endelig fundet nøglerne","da endelig hun havde fundet nøglerne","da havde hun endelig fundet nøglerne"],"a":"da hun endelig havde fundet nøglerne","r":"I en ledsætning kommer grundleddet først, så biordet, og derefter det bøjede verbum: 'hun endelig havde'."},
{"l":7377,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvilket ord passer i sætningen: 'Hun gabte og virkede helt ___ i mine feriebilleder.'","o":["uinteressant","uinteresseret","uforståelig","ubegribelig"],"a":"uinteresseret","r":"Den person, der ikke har lyst til at høre om noget, er uinteresseret. Det, der ikke er værd at høre om, er uinteressant."},
{"l":7398,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvad kaldes en fortælling, hvor personer og hændelser konsekvent står for noget andet, så hele teksten får en dobbelt betydning?","o":["anekdote","reportage","allegori","limerick"],"a":"allegori","r":"I en allegori svarer hele historien til noget andet. Handlingen skal altså læses som et billede, ikke kun bogstaveligt."},
{"l":7412,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvilken genre er en kort, ofte morsom beretning om en bestemt hændelse med en pointe til sidst?","o":["kronik","roman","ballade","anekdote"],"a":"anekdote","r":"En anekdote er en lille historie om noget, nogen har oplevet. Den er kort og lever af sin pointe."},
{"l":7432,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"I hvilken sætning er 'der' et formelt grundled og ikke et henførende ord?","o":["Der står en cykel i gården.","Manden, der ringede, var venlig.","Bogen, der lå her, er væk.","Hun, der vandt, blev glad."],"a":"Der står en cykel i gården.","r":"'Der' står her på grundleddets plads, mens det egentlige grundled er 'en cykel'. I de andre sætninger indleder 'der' en relativsætning."},
{"l":7454,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket led siger 'rød' noget om i: 'Vi malede døren rød.'?","o":["Vi","døren","malede","hele sætningen"],"a":"døren","r":"Det er døren, der bliver rød. 'Rød' er et omsagnsled til genstandsleddet, ikke til grundleddet."},
{"l":7476,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Holdet 'intensiverer' træningen før finalen. Hvad betyder det?","o":["de træner mindre og lettere","de træner et andet sted","de træner hårdere og mere","de træner hver for sig"],"a":"de træner hårdere og mere","r":"At intensivere er at gøre noget stærkere eller mere koncentreret. Avisen skriver for eksempel, at en indsats bliver intensiveret."},
{"l":7498,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvad kaldes en ytring uden verballed, for eksempel 'Sikke et vejr!'?","o":["hovedsætning","ledsætning","relativsætning","sætningsemne"],"a":"sætningsemne","r":"Et sætningsemne kan stå alene og give mening, men det har ikke både grundled og verballed. Derfor er det ikke en sætning."},
{"l":7509,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvad henviser 'hvilket' til i: 'Hun bestod prøven, hvilket glædede os alle.'?","o":["hele den foregående sætning","kun navneordet 'prøven'","kun stedordet 'hun'","den person, der blev glad"],"a":"hele den foregående sætning","r":"Det var hele det, at hun bestod, som glædede os. 'Hvilket' bruges netop, når man henviser til en hel sætning."},
{"l":7530,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvad kaldes de korte oplysninger i et skuespil, der fortæller, hvordan skuespillerne skal bevæge sig?","o":["replikker","regibemærkninger","strofer","anslag"],"a":"regibemærkninger","r":"Regibemærkninger siger noget om scene, bevægelser og tonefald. De skal ikke siges højt."},
{"l":7547,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Find ordet: 'Den stejle bakke var en stor ___ for cyklisterne.'","o":["udforring","udforderning","udfordring","utfordring"],"a":"udfordring","r":"Ordet kommer af 'udfordre', så både 'ud' og den sidste del '-dring' har d."},
{"l":7572,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvilken periode hører Ludvig Holberg til?","o":["romantikken","modernismen","det moderne gennembrud","oplysningstiden"],"a":"oplysningstiden","r":"Holberg levede 1684–1754 og satte fornuften højt. Han hører til oplysningstiden, længe før romantikken."},
{"l":7591,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Da skriften blev udbredt, frygtede nogle, at folk ville holde op med at huske. Da lommeregneren kom, lød det, at ingen ville kunne regne. Nu hører vi det samme om kunstig intelligens.' Hvad vil skribenten sige?","o":["Folk har været bange for ny teknik mange gange før","Kunstig intelligens er farligere end regnemaskiner","Lommeregneren har skadet elevernes evne til at regne","Folk er blevet ringere til at huske end i gamle dage"],"a":"Folk har været bange for ny teknik mange gange før","r":"Skriften, lommeregneren og nu kunstig intelligens: Hver gang er folk bange for det nye. Skribenten siger ikke, om de har ret."},
{"l":7613,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Mange kokke fordærver maden, siger man. Men man siger også, at mange hænder gør arbejdet let. Ordsprog er praktiske: Der er altid et, der passer.' Hvad mener skribenten om ordsprog?","o":["De er altid sande, når bare man vælger det rette ordsprog","De kan give modsatte råd og beviser derfor ikke noget","De bør forbydes i køkkener, hvor mange arbejder","De siger mest om, hvordan man laver mad sammen"],"a":"De kan give modsatte råd og beviser derfor ikke noget","r":"Skribenten viser to ordsprog, der modsiger hinanden. 'Praktiske' er spydigt ment: Man kan vælge det, der støtter ens mening."},
{"l":7633,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad betyder forleddet 'pseudo' i 'pseudonym' og 'pseudovidenskab'?","o":["halv","ny","falsk","stor"],"a":"falsk","r":"'Pseudo' kommer af græsk og betyder falsk eller tilsyneladende. Et pseudonym er et opdigtet navn, og pseudovidenskab ligner kun videnskab."},
{"l":7656,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvilken videnskabsmands tanker fik stor betydning for forfatterne i det moderne gennembrud?","o":["Tycho Brahe","Galileo Galilei","Arkimedes","Charles Darwin"],"a":"Charles Darwin","r":"Darwins udviklingslære udfordrede det gamle verdensbillede og inspirerede tidens forfattere til at se nøgternt på mennesket."},
{"l":7674,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvad betyder s-formen i: 'Der findes mange slags hvaler.'?","o":["at de eksisterer","at nogen finder dem","at de finder hinanden","at de er forsvundet"],"a":"at de eksisterer","r":"'Findes' er her et verbum med egen betydning og ikke passiv af 'finde'. Det betyder, at noget er til."},
{"l":7698,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvem skrev skuespillet 'Et dukkehjem' fra 1879, der diskuterer kvindens plads i ægteskabet?","o":["August Strindberg","Henrik Ibsen","Ludvig Holberg","H.C. Andersen"],"a":"Henrik Ibsen","r":"Nordmanden Henrik Ibsen vakte stor debat med 'Et dukkehjem', der handler om Nora og hendes plads i hjemmet."},
{"l":7715,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad er rigtigt? 'Hun var ikke træt, ___ havde hun masser af energi.'","o":["tværtimodt","tvertimod","tværtimod","tvært imod"],"a":"tværtimod","r":"Ordet skrives i ét, med æ og uden t til sidst."},
{"l":7732,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Læs: 'Vi bør plante grønt på skolens tag. Planter holder på regnvandet, så kælderen ikke oversvømmes.' Hvad er belægget?","o":["Vi bør plante grønt på skolens tag","Skolens tag er stort og fladt","Kældre skal altid være tørre","Planter holder på regnvandet"],"a":"Planter holder på regnvandet","r":"Belægget er begrundelsen for påstanden. Det svarer på spørgsmålet: Hvorfor skal vi plante grønt på taget?"},
{"l":7757,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Find ordet: 'Det dyreste er ikke ___ det bedste.'","o":["nødvendigvis","nødvendivis","nødvendingvis","nødvendigvist"],"a":"nødvendigvis","r":"Ordet består af 'nødvendig' og -vis. G'et skal med, selvom det ikke høres."},
{"l":7774,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvad svækker mest afsenderens etos i et debatindlæg?","o":["Afsenderen har en relevant uddannelse","Afsenderen laver tydelige faktuelle fejl","Afsenderen henviser til pålidelige kilder","Afsenderen tager modargumenter alvorligt"],"a":"Afsenderen laver tydelige faktuelle fejl","r":"Etos handler om troværdighed. Tydelige fejl får læseren til at tvivle på afsenderen, mens de tre andre ting styrker tilliden."},
{"l":7796,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Da politikeren blev spurgt, om skolerne får flere penge næste år, svarede hun, at folkeskolen er kernen i vores samfund.' Hvad gør hun med spørgsmålet?","o":["Hun svarer ja til spørgsmålet om flere penge","Hun svarer nej til spørgsmålet om flere penge","Hun undgår at svare og siger noget, alle er enige i","Hun forklarer, hvor pengene skal hentes fra"],"a":"Hun undgår at svare og siger noget, alle er enige i","r":"Svaret er hverken ja eller nej. Hun taler om noget, som ingen er uenig i, og slipper for at love noget."},
{"l":7813,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad står der rigtigt? 'Hun var ___ ikke hjemme, for ingen åbnede døren.'","o":["tilsynelanende","tilsynneladende","tilsyneladene","tilsyneladende"],"a":"tilsyneladende","r":"Ordet består af 'til syne' og 'ladende', og det skal slutte med -ende med d."},
{"l":7830,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Selvfølgelig er en karakter et tal, som ikke siger alt. Men et termometer siger heller ikke alt om en patient, og vi smider det ikke ud af den grund.' Hvad forsvarer skribenten?","o":["At karakterer er nyttige, selv om de ikke siger alt","At karakterer siger alt, hvad man behøver at vide","At termometre er mere præcise end alle karakterer","At lægerne burde bruge karakterer til patienterne"],"a":"At karakterer er nyttige, selv om de ikke siger alt","r":"Skribenten giver ret i, at en karakter ikke siger alt. Men det gør et termometer heller ikke, og det er alligevel nyttigt."},
{"l":7853,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Vi skal bare lige kigge på hvalpene, sagde mor, da vi satte os i bilen. Men far havde lagt et gammelt tæppe på bagsædet, og i bagagerummet lå der en snor og en pose hvalpefoder. Jeg sagde ingenting, men mine ben kunne ikke holde sig i ro hele vejen derud.' Hvad regner fortælleren med?","o":["At de kun kigger på hvalpene og kører hjem igen.","At de får en hvalp med hjem.","At de skal give hvalpene foder, når de kommer derud.","At far vil ligge og sove på bagsædet på vejen hjem."],"a":"At de får en hvalp med hjem.","r":"Et tæppe, en snor og hvalpefoder skal man ikke bruge, hvis man kun skal kigge. Fortælleren kan ikke sidde stille, fordi det ligner, at der skal en hvalp med hjem."},
{"l":7874,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad betyder 'sensitiv'?","o":["stærkt opsigtsvækkende i pressen","meget fornuftig i sine valg","særlig følsom over for indtryk","meget omhyggelig med detaljer"],"a":"særlig følsom over for indtryk","r":"Den, der er sensitiv, mærker indtryk stærkt. Det må ikke forveksles med 'sensationel', som betyder opsigtsvækkende."},
{"l":7897,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad undersøger man i faget 'demografi'?","o":["landets bjerge, floder og jordbund","folkets gamle sagn og sange","vejrets udvikling over lang tid","befolkningens størrelse og sammensætning"],"a":"befolkningens størrelse og sammensætning","r":"'Demo' betyder folk, og 'grafi' betyder beskrivelse. Demografi handler for eksempel om fødselstal, alder og flytninger."},
{"l":7916,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken sætning bruger 'sin' rigtigt?","o":["Sofie fandt sin telefon under sengen.","Sin telefon lå under sengen hos Sofie.","Sofie og sin bror fandt telefonen.","Det er sin telefon, der ligger der."],"a":"Sofie fandt sin telefon under sengen.","r":"'Sin' viser tilbage til grundleddet i samme sætning. Det kan ikke selv stå i grundleddet."},
{"l":7938,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket stedord skal stå: 'Æblet var råddent, så jeg smed ___ ud.'?","o":["den","det","dem","ham"],"a":"det","r":"Stedordet skal passe i køn med det ord, det står i stedet for. 'Æblet' er intetkøn, så det hedder 'det'."},
{"l":7957,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad betyder det at 'sætte tæring efter næring'?","o":["at spise lidt mad, når man ikke er sulten","at rette sin indsats mod det vigtigste","ikke at bruge flere penge, end man tjener","at sætte penge i banken hver måned"],"a":"ikke at bruge flere penge, end man tjener","r":"Tæring er det, man bruger, og næring er det, man tjener. Rådet er altså, at udgifterne må følge indtægterne."},
{"l":7979,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad betyder det at 'skyde gråspurve med kanoner'?","o":["at give op over for en meget stærkere modstander","at skræmme andre med store ord og tomme trusler","at sigte efter noget, der er helt umuligt at nå","at bruge alt for store midler på et lille problem"],"a":"at bruge alt for store midler på et lille problem","r":"En kanon er alt for voldsom, når man vil ramme en lille fugl. Udtrykket bruges om indgreb, der slet ikke står mål med problemet."},
{"l":7998,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Læs: 'Jeg skal lige en tur på det lille hus, sagde moster ved middagsbordet.' Hvad kaldes det at bruge en mild omskrivning som 'det lille hus'?","o":["eufemisme","hyperbel","oxymoron","allitteration"],"a":"eufemisme","r":"En eufemisme er et pænere ord for noget, der kan være pinligt at sige ligeud. Her er 'det lille hus' et pænt ord for toilettet."},
{"l":8015,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Konjunktiv bruges til ønsker: 'Det gå dig vel på rejsen!' Hvilken anden verbalform ligner 'gå' her?","o":["nutid","navneform","datid","kort tillægsform"],"a":"navneform","r":"Konjunktiv har samme form som navneformen: 'gå'. Nutid ville hedde 'går', og sætningen fortæller jo ikke noget, men ønsker noget."},
{"l":8035,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'En afstemning om klimatiltag på skolen gav dette resultat: 50 procent for, 30 procent imod og 20 procent ved ikke. Avis A skriver: Kun 30 procent er imod. Avis B skriver: Kun halvdelen er for.' Hvad viser de to sætninger?","o":["Avis A og Avis B bruger forskellige undersøgelser","Den ene avis har regnet forkert med procenterne","Ordet 'kun' får de samme tal til at lyde forskelligt","Avis A og Avis B er enige i deres vurdering"],"a":"Ordet 'kun' får de samme tal til at lyde forskelligt","r":"Begge sætninger er rigtige, men 'kun' lægger hver sin vurdering ind. A får modstanden til at virke lille, B får opbakningen til at virke lille."},
{"l":8055,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"I en debat siger Liv: 'Du ved ingenting om det, for du fik jo et dårligt resultat i matematik.' Hvad kaldes den type angreb?","o":["ad hoc","status quo","pro et contra","ad hominem"],"a":"ad hominem","r":"'Ad hominem' er latin for 'mod personen'. Liv angriber sin modstander i stedet for sagen, og det er et usagligt argument."},
{"l":8078,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad betyder forleddet 'retro' i 'retrospektiv'?","o":["tilbage","frem","imod","under"],"a":"tilbage","r":"'Retro' er latin for 'tilbage'. En retrospektiv udstilling ser tilbage på en kunstners værker gennem mange år."},
{"l":8100,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad er et 'gerontokrati'?","o":["et styre, hvor de rigeste har magten","et styre, hvor de ældste har magten","et styre, hvor hæren har magten","et styre, hvor hele folket har magten"],"a":"et styre, hvor de ældste har magten","r":"'Geron' er græsk for olding, og '-krati' betyder styre. Samme led findes i 'demokrati', hvor 'demos' er folket."},
{"l":8116,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvad kaldes verdens undergang i nordisk mytologi?","o":["Valhal","Midgård","Ragnarok","Yggdrasil"],"a":"Ragnarok","r":"Ragnarok er det store slag, hvor guder og jætter kæmper, og verden går under. Valhal er Odins hal."},
{"l":8138,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Idrætsklubben gør en 'præventiv' indsats mod skader. Hvad betyder det?","o":["at indsatsen skal behandle dem, der er skadet","at indsatsen varer hele sæsonen","at indsatsen er frivillig for spillerne","at indsatsen skal forhindre, at de sker"],"a":"at indsatsen skal forhindre, at de sker","r":"Præventiv betyder forebyggende. Ordet kommer af latin og betyder 'at komme før', altså at nå frem, før problemet opstår."},
{"l":8162,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvorfor er semikolon forkert i 'Da vi kom hjem; spiste vi.'?","o":["Fordi første del er en ledsætning","Fordi sætningen er alt for kort","Fordi 'vi' står to gange i sætningen","Fordi semikolon kun står ved tal"],"a":"Fordi første del er en ledsætning","r":"Semikolon kræver en selvstændig sætning på begge sider. Efter ledsætningen skal der komma."},
{"l":8183,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Forskere fulgte 200 elever i 8. klasse på én skole i et halvt år. Elever, der læste på papir, huskede mere af teksterne end elever, der læste på skærm. Alle teksterne var fagtekster om naturfag. Forskerne skriver, at resultatet ikke uden videre kan overføres til andre tekster og andre elever.' Hvilken konklusion holder sig inden for forskernes forbehold?","o":["Alle elever lærer mest, hvis de læser alle slags tekster på papir","Eleverne i undersøgelsen huskede fagtekster bedre fra papir end fra skærm","Skærme gør det sværere at huske, uanset hvad man læser på dem","Undersøgelsen siger slet ikke noget om de 200 elever på skolen"],"a":"Eleverne i undersøgelsen huskede fagtekster bedre fra papir end fra skærm","r":"En konklusion må kun gælde det, der faktisk er undersøgt: disse elever og denne slags tekster. To af de andre svar går for langt, og det sidste afviser resultatet, selv om forskerne kun sætter en grænse."},
{"l":8202,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket stedord bruges som meget høflig tiltale til en fremmed i formelt sprog?","o":["du","I","De","vi"],"a":"De","r":"Høflig tiltale med stort D er gået af brug de fleste steder, men findes stadig i meget formelt sprog."},
{"l":8224,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket stedord skal stå: 'Man skal passe på ___ egne ting.'?","o":["ens","hans","deres","sine"],"a":"sine","r":"Når 'man' er grundled i sætningen, viser man tilbage med 'sin/sit/sine'. 'Ens' bruges, når 'man' ikke er grundled i samme sætning."},
{"l":8246,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken form passer: 'At spille skak er ___.'?","o":["sjovt","sjov","sjove","sjovs"],"a":"sjovt","r":"Prøv at sætte 'det' i stedet for 'at spille skak': 'Det er sjovt.' Et udtryk med 'at' regnes som intetkøn, så tillægsordet får -t."},
{"l":8265,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad gør man, når man 'går over Rubicon'?","o":["man rejser til et land, man ikke har set før","man tager et skridt, der ikke kan gøres om","man krydser en grænse uden at have papirer","man når sit mål efter et langt og sejt arbejde"],"a":"man tager et skridt, der ikke kan gøres om","r":"Julius Cæsar gik med sin hær over floden Rubicon og startede dermed en borgerkrig. Udtrykket bruges om en beslutning, man ikke kan trække tilbage."},
{"l":8289,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Vælg det rigtige ord: 'Maleren blandede en ny ___ af blå.'","o":["nyance","nuanse","nuance","nuangse"],"a":"nuance","r":"Ordet kommer fra fransk og ender på -ance med c."},
{"l":8310,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvordan er en 'flegmatisk' person?","o":["livlig og altid fuld af nye ideer","mistænksom og bange for fremmede","pligtopfyldende og meget punktlig","rolig og svær at bringe ud af fatning"],"a":"rolig og svær at bringe ud af fatning","r":"Flegmatisk kommer fra den gamle lære om fire temperamenter. Den flegmatiske person er langsom, sindig og næsten umulig at gøre ophidset."},
{"l":8332,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvilket af disse værker hører til Tove Ditlevsens erindringer?","o":["Barndom","Stuk","Lykke-Per","Det forsømte forår"],"a":"Barndom","r":"'Barndom' og 'Ungdom' fra 1967 og 'Gift' fra 1971 er Tove Ditlevsens erindringsbøger."},
{"l":8355,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad er en 'antagonist' i en fortælling?","o":["hovedpersonen selv","modspilleren til hovedpersonen","fortælleren uden for historien","hovedpersonens bedste ven"],"a":"modspilleren til hovedpersonen","r":"'Anti' betyder imod, og 'agon' betyder kamp. Antagonisten kæmper mod hovedpersonen, som kaldes protagonisten."},
{"l":8377,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Jeg lovede at ringe, når jeg var kommet frem. Jeg tog telefonen op på stationen. Jeg tog den op igen i bussen. Da jeg nåede kollegiet, lagde jeg den i skuffen.' Hvad viser rækken af handlinger?","o":["At fortælleren har mistet sin telefon undervejs på turen","At fortælleren ikke kan huske at have lovet at ringe","At fortælleren ikke har lyst til at ringe","At fortælleren ikke har dækning på stationen og i bussen"],"a":"At fortælleren ikke har lyst til at ringe","r":"Telefonen kommer frem to gange, men fortælleren ringer ikke, og til sidst ryger den i skuffen. Det gør man ikke, hvis man har lyst til at ringe."},
{"l":8400,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvad er forskellen på 'Butikken er lukket' og 'Butikken bliver lukket'?","o":["Den første er bydeform, den anden er indikativ.","Den første er nutid, den anden er datid.","Den første er aktiv, den anden er konjunktiv.","Den første er en tilstand, den anden en handling."],"a":"Den første er en tilstand, den anden en handling.","r":"'Er lukket' beskriver, hvordan butikken er nu. 'Bliver lukket' viser, at nogen er i gang med at lukke den."},
{"l":8416,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvem udgav i 1800-tallet tyske folkeeventyr som 'Hans og Grete'?","o":["Brødrene Grimm","Brødrene Schlegel","Brødrene Humboldt","Brødrene Mann"],"a":"Brødrene Grimm","r":"Jacob og Wilhelm Grimm samlede folkeeventyr og udgav dem fra 1812."},
{"l":8443,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Find stavemåden: 'Efter faldet på cyklen fik han en ___.'","o":["hjernerysselse","hjernerystelse","hjærnerystelse","hjernerøstelse"],"a":"hjernerystelse","r":"Ordet består af 'hjerne' og 'rystelse'. Hjerne skrives med stumt h og e."},
{"l":8458,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Læs: 'Karla vil vinde svømmestævnet. Hendes træner hjælper hende, men hendes egen frygt holder hende tilbage.' Hvem eller hvad er modstanderen i aktantmodellen?","o":["Træneren","Svømmestævnet","Karlas egen frygt","Sejren"],"a":"Karlas egen frygt","r":"En modstander behøver ikke at være en person. Her er det Karlas frygt, der står i vejen for målet."},
{"l":8483,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Vandreren sad ved kilden og lod sig 'vederkvæge'. Hvad skete der?","o":["han fik en forkølelse","han fik kolde fødder","han faldt i søvn","han fik nye kræfter"],"a":"han fik nye kræfter","r":"'Vederkvæge' er et gammeldags ord for at forfriske og styrke. Vandreren hviler sig og drikker af kilden, så han får det bedre."},
{"l":8500,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"I starten af en roman tør Yasmin ikke sige noget i klassen. Til sidst holder hun tale foran hele skolen. Hvad kendetegner Yasmin som figur?","o":["Hun er en rund karakter, der udvikler sig","Hun er en flad karakter uden nogen udvikling","Hun er en biperson, der ikke betyder noget","Hun er en neutral fortæller af handlingen"],"a":"Hun er en rund karakter, der udvikler sig","r":"Yasmin forandrer sig gennem historien. En person, der udvikler sig og har flere sider, kaldes rund."},
{"l":8525,"g":8,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Nogle hunde er farlige. Bella er en hund. Altså er Bella farlig.' Hvad er fejlen i slutningen?","o":["Bella behøver ikke at være en rigtig hund","Bella behøver ikke at være en af de farlige","Hunde er aldrig farlige for mennesker","Sætningerne står i den forkerte rækkefølge"],"a":"Bella behøver ikke at være en af de farlige","r":"Der står kun, at nogle hunde er farlige. Så kan Bella sagtens være en af de andre. Slutningen ville kun holde, hvis der stod 'alle'."},
{"l":8543,"g":8,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvad kalder man det, når et ord fra talesprog pludselig optræder i en formel tekst?","o":["rim","allitteration","stilbrud","gentagelse"],"a":"stilbrud","r":"Et stilbrud er et skift i sproglig stil, som falder ud af resten. Det kan være en fejl, men også et bevidst virkemiddel."},
{"l":8570,"g":8,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Læs: 'Sneen er væk nu. / Kælken står stadig ved døren. / Jeg sætter den ikke ind.' Hvad handler digtet bedst om?","o":["En, der har glemt at rydde op efter sig","En, der glæder sig til, at det bliver forår","En, der er træt af at slæbe på kælken","En, der ikke vil slippe vinteren endnu"],"a":"En, der ikke vil slippe vinteren endnu","r":"Sneen er væk, men kælken må blive stående, og det er med vilje. Den, der taler, vil altså gerne holde fast i vinteren lidt endnu."},
{"l":8597,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Efter stormen blev der bygget en 'provisorisk' bro. Hvordan er den?","o":["lavet til at holde, indtil en fast løsning er klar","bygget af særligt stærkt og dyrt materiale fra udlandet","bestemt kun for gående og cyklister","opført af folk fra en fjern provins"],"a":"lavet til at holde, indtil en fast løsning er klar","r":"Provisorisk betyder midlertidig. Ordet kommer af latin 'providere', at sørge for, og har intet at gøre med provinsen."},
{"l":8619,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilken sætning er en spaltning af 'Mads reparerede cyklen i går', så Mads får fokus?","o":["I går reparerede Mads cyklen.","Det var Mads, der reparerede cyklen i går.","Cyklen blev repareret af Mads i går.","Mads reparerede i går cyklen."],"a":"Det var Mads, der reparerede cyklen i går.","r":"En spaltning deler sætningen i to med 'Det var …, der …'. Det led, der står efter 'Det var', får fokus."},
{"l":8641,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Mange sprog i Europa og Asien er indoeuropæiske. Hvilket af disse sprog hører ikke til?","o":["russisk","spansk","finsk","hindi"],"a":"finsk","r":"Finsk hører til den uralske sprogfamilie. Russisk, spansk og hindi er alle indoeuropæiske, selvom de ikke ligner hinanden meget."},
{"l":8663,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilken endelse laver tillægsordet 'ensom' om til et navneord?","o":["-ere","-est","-t","-hed"],"a":"-hed","r":"Afledningsendelsen '-hed' danner navneord af tillægsord: 'ensomhed'. De andre endelser bøjer blot tillægsordet, så det forbliver et tillægsord."},
{"l":8685,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Find den rigtige skrivemåde: 'Bogen var god, og ___ var den billig.'","o":["i øvrigt","iøvrigt","i øvrig","i øvrit"],"a":"i øvrigt","r":"Udtrykket skrives i to ord og ender på -gt."},
{"l":8707,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilken sætning har rigtig kongruens mellem grundled og tillægsord?","o":["Både taget og døren er hvidt.","Både taget og døren er hvide.","Både taget og døren er hvid.","Både tag og dør er hvidt."],"a":"Både taget og døren er hvide.","r":"To sideordnede grundled tæller som flertal, så tillægsordet skal have flertalsformen 'hvide'. Det gælder, selvom hvert led for sig står i ental."},
{"l":8728,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Hvad kendetegner minimalistisk prosa?","o":["Lange sætninger med mange svære fremmedord","Rimede strofer med et fast omkvæd","Korte sætninger, hvor det vigtigste er usagt","Grundige forklaringer af alle personers følelser"],"a":"Korte sætninger, hvor det vigtigste er usagt","r":"Minimalismen siger lidt og antyder meget. Læseren må læse mellem linjerne."},
{"l":8747,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad beskriver ordet 'dekadence'?","o":["fremgang, hvor alle får det bedre år for år","orden, hvor alle følger strenge regler","en periode på ti år","forfald, hvor folk kun går op i luksus"],"a":"forfald, hvor folk kun går op i luksus","r":"Latin 'cadere' betyder at falde. Ordet bruges om en kultur i forfald og må ikke forveksles med 'dekade', der betyder ti år."},
{"l":8770,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hele sommerferien lå Jonas på sofaen i en slags 'letargi'. Hvad betyder det?","o":["dyb sløvhed og mangel på energi","dårligt humør og stor irritation","stor glæde over at have fri","nysgerrighed efter alt det nye i verden"],"a":"dyb sløvhed og mangel på energi","r":"Letargi er en tilstand, hvor man næsten ikke kan tage sig sammen til noget. Ordet er beslægtet med Lethe, glemslens flod i den græske myte."},
{"l":8790,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Hvad er rigtigt? 'Læreren er ___ og gør altid, hvad hun har sagt.'","o":["konsikvent","konsekvent","konsekvænt","konsekvend"],"a":"konsekvent","r":"Tillægsordet ender på -ent med t. Det er navneordet, der ender på -ens."},
{"l":8807,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad er en 'kardinalfejl'?","o":["en lille fejl, der næsten ikke ses","en fejl, der er begået af en biskop","en afgørende og særlig alvorlig fejl","en fejl, som let kan rettes igen"],"a":"en afgørende og særlig alvorlig fejl","r":"Latin 'cardo' betyder hængsel. En kardinalfejl rammer det, som alt andet drejer sig om."},
{"l":8830,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"I et drama står hovedpersonen over for sin modspiller. Hvad kaldes hovedpersonen med et fagord?","o":["antagonist","statist","suffløse","protagonist"],"a":"protagonist","r":"Græsk 'protos' betyder først. Antagonisten er modspilleren, og en statist står bare i baggrunden."},
{"l":8850,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Vælg rigtigt: 'Udsigten fra bjerget var ___.'","o":["overvældende","overvældene","overvælende","overvældente"],"a":"overvældende","r":"Ordet kommer af 'overvælde' og får -ende, så d'et skal med begge steder."},
{"l":8872,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilken spaltning sætter fokus på 'bogen' i: 'Aisha lånte bogen af sin moster.'","o":["Det var Aisha, der lånte bogen af sin moster.","Det var bogen, Aisha lånte af sin moster.","Det var af sin moster, Aisha lånte bogen.","Det var hendes moster, der lånte Aisha bogen."],"a":"Det var bogen, Aisha lånte af sin moster.","r":"Det led, der skal have fokus, står efter 'Det var'. Når leddet er genstandsled, kan 'der' ikke bruges; her kan 'som' stå eller udelades."},
{"l":8893,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Læs: 'Vi bør tage toget, medmindre det bliver aflyst.' Hvad er 'medmindre det bliver aflyst' i argumentet?","o":["påstand","belæg","forbehold","hjemmel"],"a":"forbehold","r":"Et forbehold angiver en situation, hvor påstanden ikke gælder. Det gør påstanden mere præcis."},
{"l":8912,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"I retorikken taler man om 'kairos'. Hvad er det?","o":["den rette påklædning til lejligheden","den rette rækkefølge af argumenter","den rette stemmeføring i en tale","det rette øjeblik at sige noget på"],"a":"det rette øjeblik at sige noget på","r":"Kairos er det gunstige tidspunkt. Et godt argument kan falde til jorden, hvis det kommer på det forkerte tidspunkt."},
{"l":8933,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'En løber med gps-ur snyder ikke, fordi hun kan se sin fart undervejs. Uret giver hende bare en oplysning. Derfor snyder en orienteringsløber heller ikke, hvis hun har sin position på telefonen.' Hvad skal en modstander vise for at svække sammenligningen?","o":["At netop vejfinding er det, et orienteringsløb tester","At en telefon viser positionen mere præcist end et gps-ur","At orienteringsløb er en hårdere sport end almindeligt løb","At mange orienteringsløbere i forvejen træner med gps-ur"],"a":"At netop vejfinding er det, et orienteringsløb tester","r":"En sammenligning er svag, hvis tilfældene adskiller sig på det afgørende punkt: Farten er ikke opgaven i et orienteringsløb, men det er vejfindingen. At telefonen er mere præcis, ændrer ikke på, at begge blot er oplysninger."},
{"l":8950,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Forskerne 'ekstrapolerer' ud fra de seneste ti års tal. Hvad gør de?","o":["trækker de vigtigste tal ud af materialet","regner ud, hvordan tallene vil fortsætte","sletter de tal, der ikke passer ind","finder gennemsnittet af de ti års tal"],"a":"regner ud, hvordan tallene vil fortsætte","r":"Ekstra- betyder uden for. Man regner videre og slutter noget om det, man endnu ikke har målt."},
{"l":8970,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Vælg rigtigt: 'Tigerens striber fungerer som ___ i det høje græs.'","o":["kammuflage","kamuflasje","kamuflage","kamouflage"],"a":"kamuflage","r":"På dansk skrives ordet med k og u, men endelsen -age er bevaret fra fransk."},
{"l":8993,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'I byen stillede alle deres ure efter klokken på torvet. Urmageren stillede torvets klokke efter sit eget ur. Og sit eget ur stillede han hver morgen efter klokken på torvet.' Hvad er problemet i historien?","o":["Urmageren er ikke dygtig nok til at reparere ure","Klokken på torvet slår for højt om morgenen","Byens beboere har for mange ure i deres hjem","Ingen ved, hvad klokken er, for urene følger bare hinanden"],"a":"Ingen ved, hvad klokken er, for urene følger bare hinanden","r":"Urmageren og klokken retter sig kun efter hinanden, så ingen tjekker den rigtige tid. Sådan kan det også være med kilder, der bare støtter sig til hinanden."},
{"l":9015,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"'Kommunen lukkede skolen' skrives om til 'Lukningen af skolen'. Hvilken oplysning forsvinder?","o":["hvem der gjorde det","hvad der skete","hvilket sted det gælder","at det drejer sig om en skole"],"a":"hvem der gjorde det","r":"'Lukningen af skolen' fortæller, at skolen blev lukket, men ikke af hvem. Derfor forsvinder oplysningen om, at det var kommunen."},
{"l":9036,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Læs: 'Skolen er for alle. Biblioteket er for alle. Byen er for alle.' Hvilken figur er det?","o":["anafor","epifor","kiasme","litote"],"a":"epifor","r":"Epifor er gentagelse sidst i flere sætninger. Anafor er det modsatte, altså gentagelse først."},
{"l":9055,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Instruktøren fik 'carte blanche' af filmselskabet. Hvad fik instruktøren?","o":["en advarsel om at overholde budgettet","et krav om at skrive det hele om","frie hænder til selv at bestemme","en pris for sit lange livsværk"],"a":"frie hænder til selv at bestemme","r":"Udtrykket er fransk for 'hvidt kort'. Man fik et blankt, underskrevet papir, hvor modtageren selv kunne skrive betingelserne."},
{"l":9075,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Vælg rigtigt: 'At kalde en mark med mange blomster for et blomsterhav er en ___.'","o":["metaphor","mettafor","metafoer","metafor"],"a":"metafor","r":"Ordet kommer fra græsk, men skrives med f på dansk og ét t."},
{"l":9092,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Ordet 'sjov' har fire bogstaver. Hvor mange lyde udtales der?","o":["tre","fire","to","fem"],"a":"tre","r":"Bogstaverne s og j står tilsammen for én lyd, [ɕ]. Derefter kommer o og v, så ordet har tre lyde."},
{"l":9114,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvorfor står 'aldrig' forskellige steder i 'Hun spiser aldrig fisk' og '…, fordi hun aldrig spiser fisk'?","o":["I ledsætninger står det altid sidst i sætningen.","I ledsætninger står det foran det bøjede udsagnsord.","I hovedsætninger står det altid helt først.","I ledsætninger står det foran grundleddet."],"a":"I ledsætninger står det foran det bøjede udsagnsord.","r":"I hovedsætninger står sætningsadverbialet efter det bøjede udsagnsord, men i ledsætninger står det foran. Det kan bruges til at kende de to sætningstyper fra hinanden."},
{"l":9135,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Vælg stavemåden: 'Sekretæren skrev mødets beslutninger i en ___.'","o":["protokoll","prottokol","protokol","protocol"],"a":"protokol","r":"Ordet ender med ét l i ental og skrives med k."},
{"l":9157,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Hvad sker der i H.C. Andersens eventyr 'Skyggen'?","o":["En dreng mister sin skygge og vinder prinsessen","En heks stjæler skyggerne fra byens børn om natten","En prins skjuler sig i skyggerne for sin onde bror","En skygge løsriver sig og overtager sin herres liv"],"a":"En skygge løsriver sig og overtager sin herres liv","r":"'Skyggen' er et af Andersens mørkeste eventyr. Her vender magtforholdet, så skyggen bliver herren."},
{"l":9178,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"t","variant":"authored","q":"Hvilken sætning med 'hverken' og 'eller' er tegnsat rigtigt?","o":["Hverken Omar eller Freja havde set filmen.","Hverken Omar, eller Freja havde set filmen.","Hverken, Omar eller Freja havde set filmen.","Hverken Omar eller Freja, havde set filmen."],"a":"Hverken Omar eller Freja havde set filmen.","r":"Det er ét fælles grundled uden ledsætning, så der skal ikke komma."},
{"l":9195,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Det siges, at den gamle Nielsen aldrig gik i seng uden at tælle sine penge. Det siges også, at han havde en søn et sted. Det siges så meget i sådan en by.' Hvordan forholder fortælleren sig til rygterne?","o":["Med tillid, for alle i byen ved besked med Nielsen","Med forbehold, for det kan være sladder alt sammen","Med vrede, for fortælleren er selv søn af Nielsen","Med begejstring, for fortælleren spreder dem glad"],"a":"Med forbehold, for det kan være sladder alt sammen","r":"Gentagelsen af 'det siges' og sidste sætning skaber afstand. Fortælleren bringer rygterne videre uden at stå inde for dem."},
{"l":9213,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilken formulering gør sætningen rigtig: 'Jeg ved ikke, ___ i morgen.'","o":["hvem kommer","der hvem kommer","hvem der kommer","hvem kommer der"],"a":"hvem der kommer","r":"'Hvem' er den, der kommer, altså grundleddet. Når spørgeordet er grundled i en ledsætning, skal 'der' med: 'hvem der kommer', 'hvad der sker'."},
{"l":9235,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilken omskrivning gør denne sætning mere verbal: 'Efter afslutningen af kampen var der uddeling af præmier.'","o":["Efter kampens afslutning fandt præmieuddeling sted.","Kampafslutningen blev efterfulgt af præmieuddeling.","Præmieuddelingen skete efter kampafslutningen.","Da kampen var slut, delte de præmier ud."],"a":"Da kampen var slut, delte de præmier ud.","r":"Verbal stil bruger udsagnsord i stedet for tunge navneord. 'Afslutningen' bliver til 'var slut', og 'uddeling' bliver til 'delte ud'."},
{"l":9256,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Hvilken beskrivelse passer bedst på Karen Blixens fortællestil?","o":["Gammeldags fortællekunst med historier i historier","Korte, nøgterne sætninger om hverdagen","Sproglege og små tegninger uden nogen form for handling","Hurtige replikker fra unge i en moderne storby"],"a":"Gammeldags fortællekunst med historier i historier","r":"Blixen ser sig selv som en fortæller i en gammel tradition. Hendes historier foregår ofte i fortiden og rummer nye historier i sig."},
{"l":9278,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Hvad handler 'Babettes Gæstebud' især om, ud over mad?","o":["At man ikke skal bruge penge på luksus","At en kunstner giver alt for sin kunst","At man skal være tro mod sit gamle land","At mad smager bedst, når den er enkel"],"a":"At en kunstner giver alt for sin kunst","r":"Babette bruger alt, hvad hun har, på ét måltid. Hun er kunstner, og maden er hendes kunst."},
{"l":9300,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Find stavemåden: 'Der er en ___ til, at unge læser mindre.'","o":["tentens","tendents","tendens","tendenz"],"a":"tendens","r":"Ordet har t først og d i midten, og det ender på -ens med s."},
{"l":9317,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"En anmelder roser en 'kongenial' oversættelse af en roman. Hvad mener anmelderen?","o":["Den er langt bedre end originalen","Den er hyggelig og let at læse","Den er fuld af fejl og misforståelser","Den er lige så god som originalen"],"a":"Den er lige så god som originalen","r":"Kon- betyder med, og genial kommer af 'genius', ånd. Oversætteren er altså på højde med forfatteren."},
{"l":9338,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Alle hajer er fisk. Alle fisk kan svømme. Pingviner kan svømme. Altså er pingviner hajer.' Hvad er den logiske fejl?","o":["At to dyr kan svømme, gør dem ikke til samme slags","Det passer ikke, at alle hajer er fisk","Der er for mange sætninger, før man når frem til slutningen","Pingviner kan ikke svømme, fordi de er fugle og ikke fisk"],"a":"At to dyr kan svømme, gør dem ikke til samme slags","r":"At noget kan svømme, gør det ikke til en fisk og slet ikke til en haj. Den fælles egenskab beviser ikke, at de tilhører samme gruppe."},
{"l":9360,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"t","variant":"authored","q":"Hvorfor kan man vælge at skrive 'politi-indsats' med bindestreg?","o":["Den viser, at ordet er forkortet","Den gør ordet lettere at læse","Den viser, at ordet står i flertal","Den viser, at en sætning er slut"],"a":"Den gør ordet lettere at læse","r":"Man må sætte bindestreg, hvis to ens bogstaver støder sammen og gør ordet svært at læse."},
{"l":9378,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvad sker der med tillægsordet i: 'De unge vil gerne bestemme selv.'","o":["Det bruges som udsagnsord.","Det bruges som forholdsord.","Det bruges som navneord.","Det bruges som bindeord."],"a":"Det bruges som navneord.","r":"'Unge' er et tillægsord, men her mangler navneordet: 'de unge mennesker' er blevet til 'de unge'. Så gør tillægsordet navneordets arbejde."},
{"l":9400,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvad står i forfeltet i: 'Den bog, som du gav mig, har jeg læst to gange.'","o":["Den bog","Den bog, som du","som du gav mig","Den bog, som du gav mig"],"a":"Den bog, som du gav mig","r":"Ledsætningen 'som du gav mig' hører til 'Den bog', så det hele er ét led. Først derefter kommer det bøjede udsagnsord 'har'."},
{"l":9422,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"I hvilken sætning er 'om' et bindeord?","o":["Hun spurgte, om bussen var kørt.","Filmen handler om en gammel hest.","Vi mødes igen om en time.","Han lagde armen om sin ven."],"a":"Hun spurgte, om bussen var kørt.","r":"Her indleder 'om' en ledsætning med eget grundled og udsagnsled. I de andre sætninger er 'om' et forholdsord foran et navneled."},
{"l":9445,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad er 'katharsis' ifølge Aristoteles?","o":["en dramatisk vending i handlingen","en lettelse, når følelserne får frit løb","en fortællerstemme, der kommenterer","en sprogbrug, der skal få folk til at le"],"a":"en lettelse, når følelserne får frit løb","r":"Aristoteles mente, at tragedien gennem medlidenhed og frygt renser os. Den dramatiske vending hedder derimod peripeti."},
{"l":9465,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Læs: 'Kom, lad os danse, mens solen står højt, for ingen ved, hvad morgendagen bringer.' Hvilket motiv finder du her?","o":["janteloven","hjem-ude-hjem","carpe diem","in medias res"],"a":"carpe diem","r":"Carpe diem betyder grib dagen. Digtet opfordrer til at nyde nuet, fordi tiden er kort."},
{"l":9487,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Læs: 'Vi var seks, der vidste, hvem der havde sparket bolden gennem ruden. Vi sagde ikke noget. Vi så bare på hinanden i frikvarteret og gik hver til sit.' Hvad får vi at vide, fordi fortælleren siger 'vi'?","o":["At fortælleren kender alle de andres tanker","At fortælleren selv har sparket bolden","At hele klassen godt ved, hvem der gjorde det med ruden","At de alle seks holder på hemmeligheden sammen"],"a":"At de alle seks holder på hemmeligheden sammen","r":"Der står 'vi sagde ikke noget', så tavsheden deler de alle seks. Teksten siger ikke, hvem der sparkede, eller hvad de andre tænker."},
{"l":9505,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvem har magten i et 'oligarki'?","o":["en lille, magtfuld gruppe","hele den voksne befolkning","en fyrste, der arvede tronen","de ældste i hver landsby"],"a":"en lille, magtfuld gruppe","r":"Oligo- betyder få, og -arki betyder styre. Et oligarki er altså fåmandsvælde."},
{"l":9527,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad vil et land opnå med 'protektionisme'?","o":["åbne sine grænser for al fri handel med verden","beskytte egne virksomheder med told og afgifter","sikre sig mod storme med nye, høje diger","bevare sine gamle bygninger gennem fredning"],"a":"beskytte egne virksomheder med told og afgifter","r":"Ordet kommer af 'protektion', beskyttelse. Told gør udenlandske varer dyrere, så landets egne varer står stærkere."},
{"l":9543,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilken sprogfunktion er tydeligst, når en digter skriver: 'Stille står de store sten.'","o":["den informative","den appellative","den poetiske","den metasproglige"],"a":"den poetiske","r":"I den poetiske funktion er selve sprogets form vigtig. Her skaber bogstavrimet på s-lyden en særlig klang."},
{"l":9568,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"t","variant":"authored","q":"Efter hvilket ord skal der stå komma: 'Medmindre du siger nej tager vi af sted i morgen.'?","o":["siger","tager","sted","nej"],"a":"nej","r":"'Medmindre' indleder en ledsætning, som slutter efter 'nej'."},
{"l":9587,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilken betydning giver 'van-' i 'vanrøgt' og 'vanære'?","o":["noget dårligt eller mangelfuldt","noget nyt og ukendt","noget stort og vigtigt","noget gammelt og brugt"],"a":"noget dårligt eller mangelfuldt","r":"Forstavelsen 'van-' betyder dårlig eller manglende. Vanrøgt er dårlig pasning, og vanære er tab af ære."},
{"l":9609,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket ord ender på lyden [ə], der kaldes schwa?","o":["kano","kone","koner","kopi"],"a":"kone","r":"Schwa er den svage e-lyd i en tryksvag stavelse, som i slutningen af 'kone'. 'Koner' ender på en anden lyd, [ɐ]."},
{"l":9630,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Sæt ind: 'Trappen fik et nyt ___ af stål.'","o":["gelender","gellænder","gelænder","gelændder"],"a":"gelænder","r":"Ordet skrives med ét l, æ og -der."},
{"l":9647,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Det hævdes ofte, at ordet hygge ikke kan oversættes. Men at et ord mangler på et andet sprog, betyder ikke, at oplevelsen mangler hos dem, der taler det.' Hvilken tanke afviser skribenten?","o":["At danskere bruger ordet hygge for tit i hverdagen","At sproglige ord kan oversættes med flere andre ord","At andre sprog også kan have særlige hverdagsord","At man kun kan opleve det, man har et ord for"],"a":"At man kun kan opleve det, man har et ord for","r":"Skribenten skelner mellem ord og oplevelse. Fraværet af et ord beviser ikke, at følelsen er ukendt."},
{"l":9672,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"t","variant":"authored","q":"Hvilken sætning om den røde planet er rigtig?","o":["Mars' overflade er rød og støvet.","Mars's overflade er rød og støvet.","Marss overflade er rød og støvet.","Mar's overflade er rød og støvet."],"a":"Mars' overflade er rød og støvet.","r":"Også navne på planeter, der ender på s, får kun apostrof i genitiv."},
{"l":9692,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Den nye direktør overtog en 'augiasstald'. Hvad mødte hun?","o":["en dyr og prangende bygning midt i byens centrum","et stort rod, der krævede en grundig oprydning","en flok trofaste og dygtige medarbejdere","et gammelt firma med rige traditioner"],"a":"et stort rod, der krævede en grundig oprydning","r":"Herkules skulle rense kong Augias' stald, som ikke var blevet muget i årevis. Udtrykket bruges om stor uorden eller fordærv."},
{"l":9715,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad vil det sige at 'brænde sine skibe'?","o":["at slippe af med noget, man ikke bruger","at miste alle sine penge på en dårlig idé","at afskære sig selv fra at vende om","at tage hævn over en gammel fjende"],"a":"at afskære sig selv fra at vende om","r":"En hær uden skibe kan ikke trække sig tilbage. Billedet viser en beslutning, der ikke kan gøres om."},
{"l":9730,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Bybørn har oftere allergi end børn på landet. Nogle forskere har foreslået, at kontakt med dyr tidligt i livet beskytter. Men familier med allergi i forvejen fravælger måske dyr og flytter måske væk fra landet.' Hvad gør den sidste sætning ved forklaringen?","o":["Den beviser, at dyr aldrig har nogen betydning for allergi","Den viser, at forskerne har talt med for få familier","Den støtter, at dyr beskytter børn mod allergi","Den siger, at allergien måske holder dyrene væk"],"a":"Den siger, at allergien måske holder dyrene væk","r":"Måske er det allergien, der fører til færre dyr, og ikke færre dyr, der fører til allergi. Teksten afviser ikke forklaringen, men sår tvivl."},
{"l":9752,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Domme slutter stadig med ordene 'Thi kendes for ret'. Hvad kaldes et gammeldags ord som 'thi'?","o":["arkaisme","neologisme","eufemisme","slang"],"a":"arkaisme","r":"En arkaisme er et ord, der er gået af brug i almindeligt sprog. Det lever kun videre i særlige sammenhænge, her i retssproget."},
{"l":9775,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"En forsker kalder en gammel målemetode for 'obsolet'. Hvad mener hun?","o":["at den er uklar og svær at forstå","at den ikke bruges længere","at den kun er kendt af få forskere","at den er dyr og tager lang tid"],"a":"at den ikke bruges længere","r":"Obsolet kommer af latin og betyder, at noget er gået af brug. Ordet må ikke forveksles med 'obskur', der handler om noget ukendt eller uklart."},
{"l":9795,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Hvilken roman af James Joyce fra 1922 foregår i løbet af én dag i Dublin?","o":["Processen","Forvandlingen","Ulysses","Moby Dick"],"a":"Ulysses","r":"'Ulysses' følger Leopold Bloom gennem én dag i Dublin. Romanen er kendt for sin bevidsthedsstrøm."},
{"l":9814,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Hvis vi giver én elev ekstra tid til prøven, må vi give alle ekstra tid. Og hvis alle får ekstra tid, er det ingen hjælp.' Hvad tager skribenten for givet, som man kan være uenig i?","o":["At ekstra tid kan hjælpe en elev til prøven","At prøverne er for lette for de fleste elever på skolen","At nogen elever har brug for mere tid end andre","At retfærdighed betyder, at alle skal have det samme"],"a":"At retfærdighed betyder, at alle skal have det samme","r":"'Må give alle' betyder, at alle skal have det samme, for at det er fair. Men man kan også sige, at det er fair at hjælpe den, der har brug for det."},
{"l":9837,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Hvis en bog er god, har den fået priser. Denne bog har ikke fået priser. Altså er den ikke god.' Hvad kan man indvende, selv om slutningen følger logisk af sætningerne?","o":["Den første sætning passer ikke, for gode bøger får ikke altid priser","Slutningen kommer i den forkerte ende af sætningerne","Ingen bog har nogensinde fået priser for at være god","Den anden sætning passer ikke, fordi bogen har fået priser"],"a":"Den første sætning passer ikke, for gode bøger får ikke altid priser","r":"En slutning kan være rigtigt bygget og alligevel forkert, hvis den første sætning ikke passer. Mange gode bøger har aldrig fået priser."},
{"l":9855,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Find den rigtige stavemåde: 'Før forsøget opstillede eleverne en ___ om, hvad der ville ske.'","o":["hypothese","hypotese","hyppotese","hypotesse"],"a":"hypotese","r":"Ordet kommer fra græsk, skrives med y og ét p, og på dansk er h'et efter t væk."},
{"l":9880,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Læs: 'Bogen er pålidelig, fordi den selv siger, at den er pålidelig.' Hvilken argumentationsfejl er det?","o":["ad hominem","stråmandsargument","cirkelslutning","glidebaneargument"],"a":"cirkelslutning","r":"Argumentet forudsætter det, som skal bevises. Man bevæger sig i ring og kommer ikke nærmere en begrundelse."},
{"l":9900,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Hvad står der? 'Forfatteren skrev under et ___, så ingen kendte hendes rigtige navn.'","o":["psedonym","pseudonum","seudonym","pseudonym"],"a":"pseudonym","r":"Ordet kommer fra græsk og begynder med pseu-, og det ender på -onym med y."},
{"l":9917,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Slottet tilhører kongen af Danmark. Hvilken form er rigtig med gruppeejefald?","o":["kongen af Danmarks slot","kongens af Danmark slot","kongens af Danmarks slot","kongen af Danmark slot"],"a":"kongen af Danmarks slot","r":"Ved gruppeejefald står -s på det sidste ord i hele udtrykket. Det er kongen af Danmark, der ejer, så -s lægges på 'Danmark'."},
{"l":9939,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Der findes ingen skrevne tekster på urindoeuropæisk. Hvordan kender forskerne så til sproget?","o":["Det kendes fra runer på gravsten.","Det rekonstrueres ud fra senere sprog.","Det kendes fra gamle lydoptagelser.","Det tales stadig i dele af Asien."],"a":"Det rekonstrueres ud fra senere sprog.","r":"Forskerne sammenligner beslægtede sprog og slutter sig bagud til det fælles ursprog. Det er en rekonstruktion, ikke noget, man har læst."},
{"l":9960,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Læs med tryk på de store bogstaver: 'HØsten KOMmer, STORken FLYver.' Hvilken versefod er der her?","o":["jambe","daktyl","trokæ","anapæst"],"a":"trokæ","r":"Hver gruppe har først en betonet stavelse og så en ubetonet. Det er en trokæ."},
{"l":9982,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Læs: 'Hver aften tænder Aksel fyrtårnets lampe, selvom skibene for længst sejler efter satellit. Han pudser glasset. Han skriver vejret i logbogen. Turister spørger, om han ikke keder sig. Nej, siger han. Der er jo stadig et hav.' Hvad kan man bedst slutte om Aksel?","o":["Han har ikke opdaget, at skibene ikke længere bruger lyset","Han keder sig egentlig, men vil ikke sige det til turisterne","Han synes, at satellitterne har gjort havet farligere for skibe","Han kan lide sit arbejde, også selvom ingen har brug for det"],"a":"Han kan lide sit arbejde, også selvom ingen har brug for det","r":"Han passer arbejdet hver aften og svarer roligt nej. Der er ikke noget i teksten, der tyder på, at han lyver eller keder sig."}
]$$::jsonb) AS e
JOIN (VALUES
  ('s', 'stavning', 'recall', 'factual', 'surface_association'),
  ('o', 'ordforråd', 'recall', 'factual', 'surface_association'),
  ('g', 'grammatik', 'application', 'applied', 'overgeneralization'),
  ('t', 'tegnsætning', 'application', 'applied', 'overgeneralization'),
  ('l', 'læseforståelse', 'comprehension', 'conceptual', 'surface_association'),
  ('f', 'litteratur', 'analysis', 'inferential', 'surface_association')
) AS m(k, concept, skill, dtype, mis) ON m.k = e->>'k';
